const EMPTY_SEARCH: SearchState = {
  ngayCt1: '',
  ngayCt2: '',
  soCt1: '',
  soCt2: '',
  maKh: '',
  dienGiai: '',
  maKho: '',
  maVt: '',
  soSo: '',
  maPost: '9',
  maGd: '',
  maQuyen: '',
  tkNo: '',
  tkCo: '',
  tkVt: '',
  tkGv: '',
  tkThue: '',
  tkCk: '',
  nhVt1: '',
  nhVt2: '',
  nhVt3: '',
  nhVt4: '',
  nhVt5: '',
  tien1: '',
  tien2: '',
  maPhi: '',
  maVv: '',
  maHd: '',
  maSp: '',
  maKu: '',
  maTtln: '',
  maTtcp: '',
  maBp: '',
  maHs: '',
  maCd: '',
  maTd1: '',
  maTd2: '',
  maTd3: '',
  maTd4: '',
  maTd5: '',
  locNsd: false,
};

const TEXT_KEYS = [
  'soCt1', 'soCt2', 'maKh', 'dienGiai', 'maKho', 'maVt', 'soSo', 'maQuyen',
  'tkNo', 'tkCo', 'tkVt', 'tkGv', 'tkThue', 'tkCk',
  'nhVt1', 'nhVt2', 'nhVt3', 'nhVt4', 'nhVt5',
  'maPhi', 'maVv', 'maHd', 'maSp', 'maKu', 'maTtln', 'maTtcp',
  'maBp', 'maHs', 'maCd', 'maTd1', 'maTd2', 'maTd3', 'maTd4', 'maTd5',
] as const;

function showDate(value: string | null | undefined): string {
  if (!value) return '';
  const parsed = parseISO(value);
  if (Number.isNaN(parsed.getTime())) return value;
  return format(parsed, 'dd/MM/yyyy');
}

function showMoney(value: number | null | undefined): string {
  return new Intl.NumberFormat('vi-VN', { maximumFractionDigits: 4 }).format(value ?? 0);
}

function moneyQuery(value: string): number | undefined {
  const text = value.trim();
  if (!text) return undefined;
  const parsed = Number(text.replace(',', '.'));
  if (!Number.isFinite(parsed) || parsed === 0) return undefined;
  return parsed;
}

function toQuery(state: SearchState): OrderIssueFilterQuery {
  const query: OrderIssueFilterQuery = {
    maPost: state.maPost === '3' || state.maPost === '7' ? state.maPost : '9',
  };
  if (state.ngayCt1) query.ngayCt1 = state.ngayCt1;
  if (state.ngayCt2) query.ngayCt2 = state.ngayCt2;
  TEXT_KEYS.forEach(key => {
    const value = state[key].trim();
    if (value) query[key] = value;
  });
  if (state.maGd === '4') query.maGd = '4';
  const tien1 = moneyQuery(state.tien1);
  const tien2 = moneyQuery(state.tien2);
  if (tien1 !== undefined) query.tien1 = tien1;
  if (tien2 !== undefined) query.tien2 = tien2;
  if (state.locNsd) query.locNsd = true;
  return query;
}

const PxlListPage: React.FC = () => {
  const navigate = useNavigate();
  const dispatch = useAppDispatch();
  const [search, setSearch] = useState<SearchState>(EMPTY_SEARCH);
  const [items, setItems] = useState<OrderIssueListItem[]>([]);
  const [filtering, setFiltering] = useState(false);
  const [selectedSttRec, setSelectedSttRec] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [deleting, setDeleting] = useState(false);

  const patch = (next: Partial<SearchState>) => setSearch(prev => ({ ...prev, ...next }));

  const applyRows = (rows: OrderIssueListItem[]) => {
    setItems(rows);
    setSelectedSttRec(prev => (rows.some(row => row.sttRec === prev) ? prev : ''));
  };

  const loadEmpty = async () => {
    setError('');
    setLoading(true);
    try {
      applyRows(await listOrderIssues({}));
    } catch (err) {
      setItems([]);
      setSelectedSttRec('');
      setError(err instanceof Error ? err.message : 'Không tải được danh sách phiếu xuất kho theo lệnh');
    } finally {
      setLoading(false);
    }
  };

  const runSearch = async (state: SearchState) => {
    setFiltering(true);
    setError('');
    setLoading(true);
    try {
      applyRows(await listOrderIssues(toQuery(state)));
    } catch (err) {
      setItems([]);
      setSelectedSttRec('');
      setError(err instanceof Error ? err.message : 'Không tải được danh sách phiếu xuất kho theo lệnh');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadEmpty();
  }, []);

  const onSearch = () => {
    void runSearch(search);
  };

  const onRefresh = () => {
    if (!filtering) {
      void loadEmpty();
      return;
    }
    void runSearch(search);
  };

  const onDelete = async () => {
    if (!selectedSttRec || deleting) return;
    setDeleting(true);
    setError('');
    try {
      await deleteOrderIssue(selectedSttRec);
      dispatchAppToast(dispatch, { message: 'Đã xóa phiếu xuất kho theo lệnh', type: 'success' });
      setSelectedSttRec('');
      if (filtering) await runSearch(search);
      else await loadEmpty();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Xóa thất bại');
    } finally {
      setDeleting(false);
    }
  };

  const onEnter = (event: React.KeyboardEvent<HTMLElement>) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      onSearch();
    }
  };

  const noSelection = !selectedSttRec;
  const emptyText = filtering ? 'Không tìm thấy phiếu xuất kho theo lệnh' : 'Không có phiếu xuất kho theo lệnh';

  return (
    <div className={df.page} data-testid="ct-pxl-list">
      <h1 data-testid="ct-pxl-title">Phiếu xuất kho theo lệnh</h1>
      <div>
        <Button variant="secondary" data-testid="ct-pxl-toolbar-refresh-btn" onClick={onRefresh} loading={loading}>
          Làm mới
        </Button>
        <Button variant="primary" data-testid="ct-pxl-toolbar-add-btn" onClick={() => navigate('/bh/pxl/them')}>
          Thêm
        </Button>
        <Button
          variant="secondary"
          data-testid="ct-pxl-toolbar-edit-btn"
          disabled={noSelection}
          onClick={() => navigate(`/bh/pxl/${encodeURIComponent(selectedSttRec)}`)}
        >
          Sửa
        </Button>
        <Button
          variant="secondary"
          data-testid="ct-pxl-toolbar-view-btn"
          disabled={noSelection}
          onClick={() => navigate(`/bh/pxl/${encodeURIComponent(selectedSttRec)}?mode=view`)}
        >
          Xem
        </Button>
        <Button
          variant="secondary"
          data-testid="ct-pxl-toolbar-copy-btn"
          disabled={noSelection}
          onClick={() => navigate(`/bh/pxl/them?copyFrom=${encodeURIComponent(selectedSttRec)}`)}
        >
          Sao chép
        </Button>
        <Button
          variant="danger"
          data-testid="ct-pxl-toolbar-delete-btn"
          disabled={noSelection || deleting}
          loading={deleting}
          onClick={() => { void onDelete(); }}
        >
          Xóa
        </Button>
      </div>

      <section className={df.section} data-testid="ct-pxl-search" onKeyDown={onEnter}>
        <h2 className={df.sectionTitle}>Tìm kiếm</h2>
        <div className={df.row4}>
          <div className={df.field}>
            <label className={df.label}>Ngày từ</label>
            <Input type="date" data-testid="ct-pxl-search-ngayCt1" value={search.ngayCt1} onChange={e => patch({ ngayCt1: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Ngày đến</label>
            <Input type="date" data-testid="ct-pxl-search-ngayCt2" value={search.ngayCt2} onChange={e => patch({ ngayCt2: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Số C.từ từ</label>
            <Input data-testid="ct-pxl-search-soCt1" value={search.soCt1} onChange={e => patch({ soCt1: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Số C.từ đến</label>
            <Input data-testid="ct-pxl-search-soCt2" value={search.soCt2} onChange={e => patch({ soCt2: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Đối tượng</label>
            <Input data-testid="ct-pxl-search-maKh" value={search.maKh} onChange={e => patch({ maKh: e.target.value })} />
          </div>
          <div className={`${df.field} ${df.spanCol2}`}>
            <label className={df.label}>Diễn giải</label>
            <Input data-testid="ct-pxl-search-dienGiai" value={search.dienGiai} onChange={e => patch({ dienGiai: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Kho</label>
            <Input data-testid="ct-pxl-search-maKho" value={search.maKho} onChange={e => patch({ maKho: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Hàng hoá</label>
            <Input data-testid="ct-pxl-search-maVt" value={search.maVt} onChange={e => patch({ maVt: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Số lệnh</label>
            <Input data-testid="ct-pxl-search-soSo" value={search.soSo} onChange={e => patch({ soSo: e.target.value })} />
          </div>
        </div>
        <Button variant="primary" data-testid="ct-pxl-search-btn" onClick={onSearch} loading={loading}>
          Tìm
        </Button>
      </section>

      <section className={df.section} data-testid="ct-pxl-search-extra" onKeyDown={onEnter}>
        <h2 className={df.sectionTitle}>Điều kiện thêm</h2>
        <div className={df.row4}>
          <div className={df.field}>
            <label className={df.label}>Trạng thái</label>
            <Select
              data-testid="ct-pxl-search-maPost"
              value={search.maPost}
              onChange={e => patch({ maPost: e.target.value })}
              options={[
                { value: '3', label: 'Lập phiếu xuất hàng' },
                { value: '7', label: 'Đã viết hóa đơn' },
                { value: '9', label: 'Hạch toán sổ cái' },
              ]}
            />
          </div>
          <div className={df.field}>
            <label className={df.label}>Loại giao dịch</label>
            <Select
              data-testid="ct-pxl-search-maGd"
              value={search.maGd}
              onChange={e => patch({ maGd: e.target.value })}
              options={[
                { value: '', label: 'Tất cả' },
                { value: '4', label: 'Phiếu xuất theo lệnh' },
              ]}
            />
          </div>
          <div className={df.field}>
            <label className={df.label}>Quyền số</label>
            <Input data-testid="ct-pxl-search-maQuyen" value={search.maQuyen} onChange={e => patch({ maQuyen: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>TK nợ</label>
            <Input data-testid="ct-pxl-search-tkNo" value={search.tkNo} onChange={e => patch({ tkNo: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>TK có</label>
            <Input data-testid="ct-pxl-search-tkCo" value={search.tkCo} onChange={e => patch({ tkCo: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Tk hàng hóa</label>
            <Input data-testid="ct-pxl-search-tkVt" value={search.tkVt} onChange={e => patch({ tkVt: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>TK Giá vốn</label>
            <Input data-testid="ct-pxl-search-tkGv" value={search.tkGv} onChange={e => patch({ tkGv: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>TK thuế</label>
            <Input data-testid="ct-pxl-search-tkThue" value={search.tkThue} onChange={e => patch({ tkThue: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>TK CK</label>
            <Input data-testid="ct-pxl-search-tkCk" value={search.tkCk} onChange={e => patch({ tkCk: e.target.value })} />
          </div>
          {([1, 2, 3, 4, 5] as const).map(index => {
            const key = `nhVt${index}` as const;
            return (
              <div className={df.field} key={key}>
                <label className={df.label}>{`Nhóm hàng ${index}`}</label>
                <Input data-testid={`ct-pxl-search-${key}`} value={search[key]} onChange={e => patch({ [key]: e.target.value })} />
              </div>
            );
          })}
          <div className={df.field}>
            <label className={df.label}>Tiền từ</label>
            <Input inputMode="decimal" data-testid="ct-pxl-search-tien1" value={search.tien1} onChange={e => patch({ tien1: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Tiền đến</label>
            <Input inputMode="decimal" data-testid="ct-pxl-search-tien2" value={search.tien2} onChange={e => patch({ tien2: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Khoản mục</label>
            <Input data-testid="ct-pxl-search-maPhi" value={search.maPhi} onChange={e => patch({ maPhi: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Vụ việc</label>
            <Input data-testid="ct-pxl-search-maVv" value={search.maVv} onChange={e => patch({ maVv: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Hợp đồng</label>
            <Input data-testid="ct-pxl-search-maHd" value={search.maHd} onChange={e => patch({ maHd: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Sản phẩm</label>
            <Input data-testid="ct-pxl-search-maSp" value={search.maSp} onChange={e => patch({ maSp: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Khế ước</label>
            <Input data-testid="ct-pxl-search-maKu" value={search.maKu} onChange={e => patch({ maKu: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Trung tâm lợi nhuận</label>
            <Input data-testid="ct-pxl-search-maTtln" value={search.maTtln} onChange={e => patch({ maTtln: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Trung tâm chi phí</label>
            <Input data-testid="ct-pxl-search-maTtcp" value={search.maTtcp} onChange={e => patch({ maTtcp: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Phòng ban</label>
            <Input data-testid="ct-pxl-search-maBp" value={search.maBp} onChange={e => patch({ maBp: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Nhân sự</label>
            <Input data-testid="ct-pxl-search-maHs" value={search.maHs} onChange={e => patch({ maHs: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Công đoạn</label>
            <Input data-testid="ct-pxl-search-maCd" value={search.maCd} onChange={e => patch({ maCd: e.target.value })} />
          </div>
          {([1, 2, 3, 4, 5] as const).map(index => {
            const key = `maTd${index}` as const;
            return (
              <div className={df.field} key={key}>
                <label className={df.label}>{`Mã tự do ${index}`}</label>
                <Input data-testid={`ct-pxl-search-${key}`} value={search[key]} onChange={e => patch({ [key]: e.target.value })} />
              </div>
            );
          })}
          <div className={df.field}>
            <Checkbox
              label="Chỉ chứng từ của tôi"
              data-testid="ct-pxl-search-locNsd"
              checked={search.locNsd}
              onChange={e => patch({ locNsd: e.target.checked })}
            />
          </div>
        </div>
      </section>

      {error ? <div className={df.errorBanner}>{error}</div> : null}
      <div className={df.tableWrapper}>
        <table className={df.linesTable} data-testid="ct-pxl-grid">
          <thead>
            <tr>
              <th>Số C.từ</th>
              <th>Ngày C.từ</th>
              <th>Đối tượng</th>
              <th>Tên đối tượng</th>
              <th>Tổng Phát sinh</th>
              <th>Tổng Ps NT</th>
              <th>Ngoại tệ</th>
            </tr>
          </thead>
          <tbody>
            {items.map(row => {
              const selected = row.sttRec === selectedSttRec;
              return (
                <tr
                  key={row.sttRec}
                  aria-selected={selected}
                  style={selected ? { background: 'var(--ds-color-primary-bg, rgba(13, 110, 253, 0.08))' } : undefined}
                  onClick={() => setSelectedSttRec(row.sttRec)}
                >
                  <td>{row.soCt}</td>
                  <td>{showDate(row.ngayCt)}</td>
                  <td>{row.maKh}</td>
                  <td>{row.tenKh}</td>
                  <td>{showMoney(row.tTien2)}</td>
                  <td>{showMoney(row.tTienNt2)}</td>
                  <td>{row.maNt}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
      {items.length === 0 ? <div>{emptyText}</div> : null}
    </div>
  );
};

export default PxlListPage;
